      "La FPP mostra el màxim que es pot produir **amb tots els recursos existents i la tecnologia disponible**. Per tant, només es desplaça si canvien els recursos o la tecnologia.",
      "La FPP muestra el máximo que se puede producir **con todos los recursos existentes y la tecnología disponible**. Por tanto, solo se desplaza si cambian los recursos o la tecnología.",
      "The PPF shows the maximum that can be produced **with all the existing resources and the available technology**. Therefore, it only shifts if resources or technology change."
