      "**Paso 1. Forma de la FPP.** Cada bloque de 10 portátiles cuesta: $$60-45=15\\qquad 45-30=15\\qquad 30-15=15\\qquad 15-0=15$$ El coste de oportunidad es **constante** (15 móviles por cada 10 portátiles, es decir, 1,5 móviles por portátil). Por tanto, la FPP es una **recta**, no una curva cóncava. Tiene sentido: los técnicos son igual de buenos en las dos tareas, y no hay recursos «menos aptos» que encarezcan las últimas unidades.",
