      "**Paso 1. Equilibrio.** $$1100-25P=35P-100\\; \\Rightarrow \\; 1200=60P\\; \\Rightarrow \\; P^*=20$$ $$Q^*=1100-25\\cdot 20=600\\qquad \\text{Comprobación:}\\; 35\\cdot 20-100=600\\; ✓$$",
