      "**Paso 3. A 16 € (por debajo de $P^*$):** $$Q_d=1100-25\\cdot 16=700\\qquad Q_o=35\\cdot 16-100=460$$ $$Q_o-Q_d=460-700=-240$$ Negativo → **faltan** 240 horas: **exceso de demanda**. Hay jugadores que no encuentran pista y el precio tiende a **subir** hacia 20 €.",
