      "**Pas 3. Conclusió.** Tots dos desplaçaments empenyen el preu cap amunt, així que **P\\* puja amb seguretat**. En canvi, sobre la quantitat els efectes s'oposen: si la demanda es desplaça més que l'oferta, Q\\* puja; si l'oferta es desplaça més, Q\\* baixa. Sense conèixer la magnitud de cada desplaçament, **l'efecte sobre Q\\* és ambigu**.",
      "**Paso 3. Conclusión.** Los dos desplazamientos empujan el precio hacia arriba, así que **P\\* sube con seguridad**. En cambio, sobre la cantidad los efectos se oponen: si la demanda se desplaza más que la oferta, Q\\* sube; si la oferta se desplaza más, Q\\* baja. Sin conocer la magnitud de cada desplazamiento, **el efecto sobre Q\\* es ambiguo**.",
      "**Step 3. Conclusion.** Both shifts push the price up, so **P\\* certainly rises**. On the quantity, however, the effects oppose each other: if demand shifts more than supply, Q\\* rises; if supply shifts more, Q\\* falls. Without knowing the size of each shift, **the effect on Q\\* is ambiguous**."
