      "**Paso 1. Demanda.** Conocemos dos puntos: $Q_d=0$ cuando $P=18$, y $Q_d=120$ cuando $P=12$: $$a-18b=0\\qquad a-12b=120$$ Restando la primera ecuación de la segunda: $6b=120\\Rightarrow b=20$. Entonces $a=18\\cdot 20=360$. $$Q_d=360-20P$$",
      "**Step 1. Demand.** We know two points: $Q_d=0$ when $P=18$, and $Q_d=120$ when $P=12$: $$a-18b=0\\qquad a-12b=120$$ Subtracting the first equation from the second: $6b=120\\Rightarrow b=20$. Then $a=18\\cdot 20=360$. $$Q_d=360-20P$$"
