      "**Step 2. Supply.** $Q_o=0$ when $P=4$, and $Q_o=120$ when $P=12$: $$4c-d=0\\qquad 12c-d=120$$ Subtracting: $8c=120\\Rightarrow c=15$. Then $d=4\\cdot 15=60$. $$Q_o=15P-60$$"
