      "**Paso 3. Comprobación del equilibrio.** $$360-20P=15P-60\\; \\Rightarrow \\; 420=35P\\; \\Rightarrow \\; P^*=12\\qquad Q_d=360-20\\cdot 12=120\\; ✓$$",
