      "**Step 4. Social welfare.** With $P_{\\mathrm{max}}=18$ and $P_{\\mathrm{min}}=4$: $$\\mathrm{CS}=\\frac{120\\cdot (18-12)}{2}=360\\qquad \\mathrm{PS}=\\frac{120\\cdot (12-4)}{2}=480$$ $$\\mathrm{SW}=360+480+0=840$$"
