      "**Paso 4. Precio fijado en 130 € (por encima de $P^*$).** $$Q_d=3000-20\\cdot 130=400\\qquad Q_o=10\\cdot 130-300=1000$$ Ahora hay **exceso de oferta** ($Q_o-Q_d=+600$): sobran plazas. Los propietarios querrían alquilar 1.000, pero solo hay 400 conductores dispuestos a pagar 130 €: $$Q_{\\text{intercambiada}}=min(400;\\; 1000)=400$$",
      "**Step 4. Price set at €130 (above $P^*$).** $$Q_d=3000-20\\cdot 130=400\\qquad Q_o=10\\cdot 130-300=1000$$ Now there is **excess supply** ($Q_o-Q_d=+600$): there are spaces left over. Owners would like to rent out 1,000, but only 400 drivers are willing to pay €130: $$Q_{\\text{traded}}=min(400;\\; 1000)=400$$"
